
/* ============================================================
   MINING 2 — the vein. A living cavern replaces the stick men.
   The rock's tier is fed by your collection level: the binder
   literally enriches the mine. Tap to swing your own pick.
   ============================================================ */
const MG_PICKS = {"p1": {"d": "data:image/png;base64,", "w": 171, "h": 180}, "p2": {"d": "data:image/png;base64,", "w": 161, "h": 180}, "p3": {"d": "data:image/png;base64,", "w": 158, "h": 180}, "p4": {"d": "data:image/png;base64,", "w": 173, "h": 180}, "p5": {"d": "data:image/png;base64,", "w": 167, "h": 180}, "p6": {"d": "data:image/png;base64,", "w": 169, "h": 180}, "p7": {"d": "data:image/png;base64,", "w": 168, "h": 180}};
const MG_ORES = {"t1": {"d": "data:image/png;base64,", "w": 190, "h": 200}, "t2": {"d": "data:image/png;base64,", "w": 197, "h": 200}, "t3": {"d": "data:image/png;base64,", "w": 195, "h": 200}, "t4": {"d": "data:image/png;base64,", "w": 194, "h": 200}, "t5": {"d": "data:image/png;base64,", "w": 179, "h": 200}, "t6": {"d": "data:image/png;base64,", "w": 183, "h": 200}, "t7": {"d": "data:image/png;base64,", "w": 177, "h": 200}};
const MG_INGOTS = {"t1": {"d": "data:image/png;base64,", "w": 84, "h": 46}, "t2": {"d": "data:image/png;base64,", "w": 84, "h": 46}, "t3": {"d": "data:image/png;base64,", "w": 84, "h": 44}, "t4": {"d": "data:image/png;base64,", "w": 84, "h": 45}, "t5": {"d": "data:image/png;base64,", "w": 84, "h": 44}, "t6": {"d": "data:image/png;base64,", "w": 84, "h": 44}, "t7": {"d": "data:image/png;base64,", "w": 84, "h": 44}};
(function(){
const scene = document.getElementById("mineScene");
if(!scene) return;
scene.innerHTML = `<canvas id="mgCv"></canvas>
  <div class="mg-cap" id="mgCap"></div>
  <div class="mg-works" id="mgWorks"></div>`;
const cv = document.getElementById("mgCv");
const g = cv.getContext("2d");
const W = 800, H = 420;
function mgFit(){
  const dpr = Math.min(2, window.devicePixelRatio||1);
  cv.width = W*dpr; cv.height = H*dpr;
  g.setTransform(dpr,0,0,dpr,0,0);
}
mgFit();

/* ---- ore + ingot + pick images ---- */
const mgOreImgs = {}, mgIngImgs = {};
for(const k in MG_ORES){ const im = new Image(); im.src = MG_ORES[k].d; mgOreImgs[k] = im; }
for(const k in MG_INGOTS){ const im = new Image(); im.src = MG_INGOTS[k].d; mgIngImgs[k] = im; }
/* the mine's own ledger */
state.mining = state.mining || {};
state.mining.ore = state.mining.ore || {};
state.mining.ingots = state.mining.ingots || {};
state.mining.forge = state.mining.forge || 0;
state.mining.job = state.mining.job || null;
state.mining.veinSel = state.mining.veinSel || 0;   /* 0 = the richest unlocked */
/* the forged pick sharpens the whole operation: +6% rate per forge tier */
if(typeof currentMineRatePerMin === "function" && !window.__mgWrapped){
  window.__mgWrapped = true;
  const _r0 = currentMineRatePerMin;
  currentMineRatePerMin = function(){ return _r0() * (1 + 0.06*(state.mining.forge||0)) * (1 + 0.10*(((state.upgrades && state.upgrades.masterwork)||0)?1:0)); };
}
const mgPickImgs = {};
for(const k in MG_PICKS){ const im = new Image(); im.src = MG_PICKS[k].d; mgPickImgs[k] = im; }
function mgPickTier(){ return 1 + Math.min(6, state.mining.forge||0); }

/* ---- the cavern, painted once ---- */
const bg = document.createElement("canvas"); bg.width = W; bg.height = H;
(function paintCave(){
  const b = bg.getContext("2d");
  const grad = b.createLinearGradient(0,0,0,H);
  grad.addColorStop(0,"#14100e"); grad.addColorStop(0.55,"#241a12"); grad.addColorStop(1,"#181008");
  b.fillStyle = grad; b.fillRect(0,0,W,H);
  /* torch glows deep in the dark */
  for(const [tx,ty,r,c] of [[92,150,120,"255,158,64"],[708,130,140,"255,140,50"],[400,40,180,"120,90,60"]]){
    const rg = b.createRadialGradient(tx,ty,0,tx,ty,r);
    rg.addColorStop(0,`rgba(${c},0.22)`); rg.addColorStop(1,"rgba(0,0,0,0)");
    b.fillStyle = rg; b.fillRect(tx-r,ty-r,r*2,r*2);
  }
  /* stalactites */
  b.fillStyle = "#0d0a08";
  let x = -10;
  let sd = 7;
  const rnd = ()=>{ sd = (sd*16807)%2147483647; return sd/2147483647; };
  while(x < W){
    const w = 26+rnd()*60, d = 24+rnd()*70;
    b.beginPath(); b.moveTo(x,0); b.lineTo(x+w,0); b.lineTo(x+w*0.5, d); b.closePath(); b.fill();
    x += w*0.72;
  }
  /* rocky floor */
  b.fillStyle = "#1e150d";
  b.beginPath(); b.moveTo(0,H);
  for(let fx=0; fx<=W; fx+=40) b.lineTo(fx, H-34 - Math.sin(fx*0.05)*7 - rnd()*8);
  b.lineTo(W,H); b.closePath(); b.fill();
  b.fillStyle = "rgba(255,190,90,0.05)";
  b.fillRect(0,H-38,W,38);
  /* scattered rubble */
  for(let i=0;i<26;i++){
    const rx = rnd()*W, ry = H-14-rnd()*22, rr = 2+rnd()*7;
    b.fillStyle = i%3? "#2a1d12" : "#3a2a18";
    b.beginPath(); b.ellipse(rx,ry,rr,rr*0.6,0,0,7); b.fill();
  }
})();

/* ---- state ---- */
const mg = {
  t: 0, hp: 20, maxHp: 20, seed: 1, swing: 0, swingT: 99, shake: 0,
  parts: [], floats: [], shards: [], strikeAcc: 0, breaking: 0, glint: 0
};
function mgMaxTier(){
  const lvl = (state.player && state.player.level) || 1;
  const th = [1,4,8,13,19,26,34];
  let t = 1;
  for(let i=0;i<7;i++) if(lvl >= th[i]) t = i+1;
  return t;
}
/* the miner picks the seam: any unlocked tier — old veins never close */
function mgRockHp(){ return 20 - 2*Math.min(3,((state.upgrades && state.upgrades.blast)||0)); }
function mgTier(){
  const sel = state.mining && state.mining.veinSel;
  const mx = mgMaxTier();
  return sel ? Math.min(sel, mx) : mx;
}
function mgNextUnlock(){
  const lvl = (state.player && state.player.level) || 1;
  const th = [1,4,8,13,19,26,34];
  for(let i=0;i<7;i++) if(lvl < th[i]) return { tier: i+1, lvl: th[i] };
  return null;
}
function mgRate(){ try{ return currentMineRatePerMin(); }catch(e){ return 100; } }

/* ---- the boulder, seeded ---- */
function mgRockPath(ctx, cx, cy, R, seed){
  let sd = seed;
  const rnd = ()=>{ sd = (sd*16807)%2147483647; return sd/2147483647; };
  ctx.beginPath();
  const n = 11;
  for(let i=0;i<n;i++){
    const a = (i/n)*Math.PI*2;
    const r = R*(0.82 + rnd()*0.3) * (1 + 0.06*Math.sin(a*3+seed));
    const px = cx + Math.cos(a)*r, py = cy + Math.sin(a)*r*0.82;
    i ? ctx.lineTo(px,py) : ctx.moveTo(px,py);
  }
  ctx.closePath();
}
function mgDrawRock(){
  const cx = W/2, cy = H-140;
  const sh = mg.shake > 0 ? (Math.random()-0.5)*mg.shake : 0;
  const tier = mgTier();
  const meta = MG_ORES["t"+tier], im = mgOreImgs["t"+tier];
  g.save(); g.translate(sh, Math.abs(sh)*0.4);
  g.fillStyle = "rgba(0,0,0,0.45)";
  g.beginPath(); g.ellipse(cx, H-40, 118, 20, 0, 0, 7); g.fill();
  if(im && im.complete && im.naturalWidth){
    const targetW = 212;
    const w = targetW, h = targetW*(meta.h/meta.w);
    const bob = Math.sin(mg.t*1.2)*2;
    g.save();
    g.shadowColor = "rgba(255,214,120,0.5)"; g.shadowBlur = 14 + Math.sin(mg.t*2.1)*6;
    g.drawImage(im, cx-w/2, H-44-h+bob, w, h);
    g.restore();
    /* damage cracks over the face */
    const dmg = 1 - mg.hp/mg.maxHp;
    if(dmg > 0.33){ g.strokeStyle="rgba(0,0,0,0.65)"; g.lineWidth=2.4;
      g.beginPath(); g.moveTo(cx-48,H-44-h*0.75+bob); g.lineTo(cx-12,H-44-h*0.45+bob); g.lineTo(cx-40,H-44-h*0.16+bob); g.stroke(); }
    if(dmg > 0.66){ g.strokeStyle="rgba(0,0,0,0.75)"; g.lineWidth=2.8;
      g.beginPath(); g.moveTo(cx+52,H-44-h*0.7+bob); g.lineTo(cx+10,H-44-h*0.42+bob); g.lineTo(cx+44,H-44-h*0.12+bob); g.stroke();
      g.beginPath(); g.moveTo(cx-2,H-44-h*0.9+bob); g.lineTo(cx+6,H-44-h*0.55+bob); g.stroke(); }
  }
  g.restore();
}

/* ---- the pickaxe: the playtester's own art, swung by tier ---- */
function mgDrawPick(){
  const cx = W/2, cy = H-150;
  const px = cx - 196, py = cy + 42;          /* the grip */
  let ang;
  const t = mg.swingT;
  if(t < 0.2){ const p = t/0.2; ang = -2.5 + (p*p)*1.9; }        /* wind-up, then crash */
  else if(t < 0.34){ ang = -0.6 - (t-0.2)*1.0; }                  /* recoil */
  else { const p = Math.min(1,(t-0.34)/0.6); ang = -0.74 - p*0.86; }  /* settle to rest */
  const tier = mgPickTier();
  const meta = MG_PICKS["p"+tier], im = mgPickImgs["p"+tier];
  if(!(im && im.complete && im.naturalWidth)) return;
  /* the sprite's handle runs bottom-left -> head top-right (~ -45°);
     rotate so the handle axis follows the swing angle */
  const targetH = 168;
  const sc = targetH / meta.h;
  const w = meta.w*sc, h = meta.h*sc;
  const gx = w*0.14, gy = h*0.88;             /* grip point inside the sprite */
  g.save();
  g.translate(px, py);
  g.rotate(ang + 0.79);
  /* soft contact shadow of the tool */
  g.drawImage(im, -gx, -gy, w, h);
  g.restore();
}
/* ---- particles / floaters / shards ---- */
function mgSparks(x, y, n, gold){
  for(let i=0;i<n;i++) mg.parts.push({ x, y, vx:(Math.random()-0.5)*260,
    vy:-60-Math.random()*220, life:0.5+Math.random()*0.4,
    c: gold ? "255,205,80" : "220,220,225", r: 1.4+Math.random()*2.2 });
}
function mgFloat(x, y, txt, big){
  mg.floats.push({ x, y, txt, life: 1.4, big: !!big });
}
function mgBurst(){
  const cx = W/2, cy = H-146;
  const im = mgOreImgs["t"+mgTier()];
  for(let i=0;i<10;i++) mg.shards.push({ x:cx, y:cy, vx:(Math.random()-0.5)*420,
    vy:-140-Math.random()*260, rot:Math.random()*6, vr:(Math.random()-0.5)*9,
    s:14+Math.random()*22, life:1.2, im });
  mgSparks(cx, cy, 46, true);
}

/* ---- the strike ---- */
function mgHeaderRefresh(){
  try{ document.getElementById("creditCount").textContent = Math.floor(state.credits).toLocaleString();
       document.getElementById("scrapCount").textContent = Math.floor(state.scrap).toLocaleString(); }catch(e){}
}
function mgStrike(player){
  mg.swingT = 0;
  setTimeout(()=>{
    const cx = W/2, cy = H-150;
    mg.shake = player ? 7 : 4;
    mgSparks(cx-96, cy+6, player ? 16 : 8, true);   /* at the rock face, where the tip lands */
    mg.hp -= 1;
    if(player){
      const gain = Math.max(3, Math.round(mgRate()/30));   /* two seconds of passive, per swing */
      state.credits += gain;
      state.totalMined = (state.totalMined||0) + gain;
      mgFloat(cx-40+Math.random()*80, cy-70, "+"+gain.toLocaleString()+" 🪙");
      try{ window.feLedgerBump && feLedgerBump("tap"); }catch(e){}
      mgHeaderRefresh();
      try{ fbSfxSafe && fbSfxSafe("equip", 0.18); }catch(e){}
    }
    if(mg.hp <= 0){
      const tier = mgTier();
      const bonus = Math.max(250, Math.round(mgRate()*0.75*(1+0.25*(tier-1))));
      let oreN = 2 + Math.floor(Math.random()*3) + (((state.upgrades && state.upgrades.prospectorEye)||0) ? 1 : 0);
      let oreT = tier;
      if(((state.upgrades && state.upgrades.prospectorEye)||0) && Math.random() < 0.10 && tier < 7){ oreT = tier+1; }
      state.credits += bonus;
      state.totalMined = (state.totalMined||0) + bonus;
      state.scrap = (state.scrap||0) + Math.round(2 * (1 + 0.12*((state.upgrades && state.upgrades.scrapMagnet)||0)));
      state.mining.ore[oreT] = (state.mining.ore[oreT]||0) + oreN;
      mgBurst();
      mgFloat(W/2, H-230, "VEIN STRUCK  +"+bonus.toLocaleString()+" 🪙  +"+oreN+" Tier-"+oreT+" Ore"+(oreT>tier?" — RICHER than the seam!":""), true);
      mgWorksRender();
      try{ window.feLedgerBump && feLedgerBump("vein"); }catch(e){}
      mg.maxHp = mgRockHp(); mg.hp = mg.maxHp; mg.seed = (mg.seed*48271)%2147483647 || 7;
      mgHeaderRefresh();
      try{ saveState(); }catch(e){}
      try{ fbSfxSafe && fbSfxSafe("treasure", 0.4); }catch(e){}
    }
  }, 200);
}
cv.addEventListener("pointerdown", (e)=>{ e.preventDefault(); mgStrike(true); }, { passive:false });

/* ---- caption ---- */
function mgCaption(){
  const el = document.getElementById("mgCap");
  if(!el) return;
  const t = mgTier(), nx = mgNextUnlock();
  el.innerHTML = `<b>Tier ${t} Vein</b>${t < mgMaxTier() ? ` <i>(of ${mgMaxTier()} unlocked — working the old seam for its ore)</i>` : " — enriched by your collection"} · <b>Tier ${mgPickTier()} Pick</b> — forged at the smelter below` +
    (nx ? ` · <i>collection level ${nx.lvl} opens the Tier ${nx.tier} vein</i>` : ` · <i>the richest vein there is</i>`) +
    ` · tap the rock to swing your own pick`;
}
setInterval(mgCaption, 2500); mgCaption();

/* ---- the works: smelter + forge ---- */
const MG_SMELT_ORE = 5;                 /* five ore make one ingot */
function mgSmeltSecs(t){ return Math.round(45*t*Math.pow(0.8,((state.upgrades && state.upgrades.bellows)||0))); }
function mgForgeCost(next){ return { n: next, t: next-1 }; }   /* Tier-N pick: N ingots of tier N-1 */
function mgWorksRender(){
  const el = document.getElementById("mgWorks");
  if(!el) return;
  const M = state.mining;
  /* ore shelf */
  let ore = "";
  for(let t=1;t<=7;t++) if((M.ore[t]||0) > 0)
    ore += `<span class="mgw-chip"><img src="${MG_ORES["t"+t].d}"><b>×${M.ore[t]}</b></span>`;
  let ing = "";
  for(let t=1;t<=7;t++) if((M.ingots[t]||0) > 0)
    ing += `<span class="mgw-chip"><img src="${MG_INGOTS["t"+t].d}"><b>×${M.ingots[t]}</b></span>`;
  /* smelter */
  if(M.job && !M.jobs){ M.jobs=[M.job]; M.job=null; }
  M.jobs = M.jobs || [];
  const slots = 1 + (((state.upgrades&&state.upgrades.crucible)||0) ? 1 : 0);
  let smelt = M.jobs.map((jb,ji)=>{
    const left = Math.max(0, Math.ceil((jb.done - Date.now())/1000));
    return left > 0 ? `<div class="mgw-job">🔥 Tier-${jb.t} ingot — ${left}s</div>`
      : `<button class="mgw-btn hot" data-collect="${ji}">🔥 Ingot ready — collect</button>`;
  }).join("");
  if(M.jobs.length < slots){
    for(let t=1;t<=7;t++) if((M.ore[t]||0) >= MG_SMELT_ORE)
      smelt += `<button class="mgw-btn" data-smelt="${t}">Smelt T${t}: ${MG_SMELT_ORE} ore → 1 ingot (${mgSmeltSecs(t)}s)</button>`;
  }
  if(!smelt) smelt = `<div class="mgw-dim">The smelter waits — five ore of a tier makes an ingot.</div>`;
  /* forge */
  let forge;
  const next = mgPickTier()+1;
  if(next > 7) forge = `<div class="mgw-dim">⚒️ The Tier 7 pick — nothing finer was ever forged.</div>`;
  else {
    const c = mgForgeCost(next);
    const have = M.ingots[c.t]||0;
    forge = `<button class="mgw-btn ${have>=c.n?"hot":""}" data-forge="1" ${have>=c.n?"":"disabled"}>
      ⚒️ Forge the Tier ${next} pick — ${c.n}× Tier-${c.t} ingot <i>(${have}/${c.n})</i></button>`;
  }
  /* the seam selector: every unlocked vein stays open */
  const mx = mgMaxTier(), cur = mgTier();
  let seams = "";
  for(let t=1;t<=7;t++){
    const open = t <= mx;
    seams += `<button class="mgw-seam ${t===cur?"sel":""}" data-seam="${t}" ${open?"":"disabled"}
      title="${open ? "Work the Tier "+t+" vein" : "Unlocks at collection level "+[1,4,8,13,19,26,34][t-1]}">
      <img src="${MG_ORES["t"+t].d}">${open?"":"<span>🔒</span>"}</button>`;
  }
  el.innerHTML = `<div class="mgw-row mgw-seams">${seams}</div>
    ${ore||ing ? `<div class="mgw-row">${ore}${ing}</div>` : ""}
    <div class="mgw-row">${smelt}</div>
    <div class="mgw-row">${forge}</div>`;
  el.querySelectorAll("[data-seam]").forEach(b => b.onclick = ()=>{
    const t = +b.dataset.seam;
    if(t > mgMaxTier()) return;
    state.mining.veinSel = (t === mgMaxTier()) ? 0 : t;   /* picking the top re-follows your progress */
    mg.maxHp = mgRockHp(); mg.hp = mg.maxHp;                                      /* a fresh face on the new seam */
    try{ saveState(); }catch(e){}
    mgWorksRender(); mgCaption();
  });
  el.querySelectorAll("[data-smelt]").forEach(b => b.onclick = ()=>{
    const t = +b.dataset.smelt;
    const slots2 = 1 + (((state.upgrades&&state.upgrades.crucible)||0) ? 1 : 0);
    if((M.ore[t]||0) < MG_SMELT_ORE || (M.jobs||[]).length >= slots2) return;
    M.ore[t] -= MG_SMELT_ORE;
    M.jobs.push({ t, done: Date.now() + mgSmeltSecs(t)*1000 });
    try{ fbSfxSafe && fbSfxSafe("bait", 0.35); }catch(e){}
    try{ saveState(); }catch(e){}
    mgWorksRender();
  });
  el.querySelectorAll("[data-collect]").forEach(col => col.onclick = ()=>{
    const jb = (M.jobs||[])[+col.dataset.collect];
    if(!jb || Date.now() < jb.done) return;
    M.ingots[jb.t] = (M.ingots[jb.t]||0) + 1;
    try{ window.feLedgerBump && feLedgerBump("smelt"); }catch(e){}
    mgFloat(W/2, H-200, "🔥 Tier-"+jb.t+" ingot, cooled and true", true);
    M.jobs.splice(+col.dataset.collect, 1);
    try{ fbSfxSafe && fbSfxSafe("reward_good", 0.4); }catch(e){}
    try{ saveState(); }catch(e){}
    mgWorksRender();
  });
  const fg = el.querySelector("[data-forge]");
  if(fg) fg.onclick = ()=>{
    const nx = mgPickTier()+1;
    if(nx > 7) return;
    const c = mgForgeCost(nx);
    if((M.ingots[c.t]||0) < c.n) return;
    M.ingots[c.t] -= c.n;
    M.forge = nx - 1;
    mgFloat(W/2, H-220, "⚒️ THE TIER "+nx+" PICK — +6% mine rate", true);
    mgSparks(W/2, H-200, 40, true);
    try{ fbSfxSafe && fbSfxSafe("perfect", 0.5); }catch(e){}
    try{ saveState(); renderMiningStats && renderMiningStats(); }catch(e){}
    mgWorksRender(); mgCaption();
  };
}
setInterval(mgWorksRender, 1000);
mgWorksRender();

/* ---- the loop ---- */
let mgLast = performance.now();
function mgFrame(now){
  requestAnimationFrame(mgFrame);
  const dt = Math.min(0.05, (now-mgLast)/1000); mgLast = now;
  if(!cv.offsetParent) return;                     /* tab hidden: sleep */
  mg.t += dt; mg.swingT += dt;
  mg.shake = Math.max(0, mg.shake - dt*26);
  /* auto strikes pace with the mine's real rate */
  const sps = Math.min(2.2, Math.max(0.45, mgRate()/240));
  mg.strikeAcc += dt*sps;
  if(mg.strikeAcc >= 1){ mg.strikeAcc = 0; mgStrike(false); }
  /* draw */
  g.clearRect(0,0,W,H);
  g.drawImage(bg, 0, 0);
  mgDrawRock();
  mgDrawPick();
  /* hp pips */
  const frac = mg.hp/mg.maxHp;
  g.fillStyle = "rgba(0,0,0,0.5)"; g.fillRect(W/2-70, H-26, 140, 8);
  g.fillStyle = frac > 0.4 ? "#ffd35c" : "#ff8a5c"; g.fillRect(W/2-70, H-26, 140*frac, 8);
  /* particles */
  for(let i=mg.parts.length-1;i>=0;i--){
    const p = mg.parts[i];
    p.life -= dt; if(p.life<=0){ mg.parts.splice(i,1); continue; }
    p.vy += 620*dt; p.x += p.vx*dt; p.y += p.vy*dt;
    g.globalAlpha = Math.min(1, p.life*2.4);
    g.fillStyle = `rgb(${p.c})`;
    g.beginPath(); g.arc(p.x, p.y, p.r, 0, 7); g.fill();
  }
  g.globalAlpha = 1;
  /* gem shards */
  for(let i=mg.shards.length-1;i>=0;i--){
    const s = mg.shards[i];
    s.life -= dt; if(s.life<=0){ mg.shards.splice(i,1); continue; }
    s.vy += 700*dt; s.x += s.vx*dt; s.y += s.vy*dt; s.rot += s.vr*dt;
    g.save(); g.globalAlpha = Math.min(1, s.life*1.6);
    g.translate(s.x, s.y); g.rotate(s.rot);
    if(s.im && s.im.complete) g.drawImage(s.im, -s.s/2, -s.s/2, s.s, s.s);
    g.restore();
  }
  g.globalAlpha = 1;
  /* floaters */
  for(let i=mg.floats.length-1;i>=0;i--){
    const f = mg.floats[i];
    f.life -= dt; if(f.life<=0){ mg.floats.splice(i,1); continue; }
    f.y -= dt*34;
    g.globalAlpha = Math.min(1, f.life*1.4);
    g.font = f.big ? "800 21px system-ui" : "700 15px system-ui";
    g.textAlign = "center";
    g.lineWidth = 4; g.strokeStyle = "rgba(0,0,0,0.7)"; g.strokeText(f.txt, f.x, f.y);
    g.fillStyle = f.big ? "#ffd35c" : "#ffe9b0"; g.fillText(f.txt, f.x, f.y);
  }
  g.globalAlpha = 1; g.textAlign = "left";
}
requestAnimationFrame(mgFrame);
})();


